async function run() {
  const feitos = [];
  for (const m of event.items || []) {
    if (m.replied) continue;
    const j = await judge.pergunta(m);
    if (j.p < 0.5) continue;
    const r = await write.resposta({email: {de: m.from_name || m.from, assunto: m.subject, texto: m.snippet}, assinatura: params.assinatura});
    const assunto = m.subject || "(sem assunto)";
    await gmail.draft({to: m.from, subject: /^re:/i.test(assunto) ? assunto : "Re: " + assunto, body: r.text});
    feitos.push(m);
  }
  if (!feitos.length) return;
  const linhas = feitos.map(m => "• " + (m.from_name || m.from) + ": " + (m.subject || "(sem assunto)"));
  await notify.send({text: "✍️ " + (feitos.length === 1 ? "Deixei 1 rascunho" : "Deixei " + feitos.length + " rascunhos") +
    " de resposta no Gmail, para você revisar e enviar:\n" + linhas.join("\n")});
}
